import socket, struct
def dns_query(name, qtype=1, server="127.0.0.11"):
    payload=b"\xab\xcd\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00"
    for label in name.split("."):
        payload+=bytes([len(label)])+label.encode()
    payload+=b"\x00"+struct.pack(">HH",qtype,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(2)
    s.sendto(payload,(server,53))
    try:
        data,_=s.recvfrom(4096)
        ancount=struct.unpack(">H",data[6:8])[0]
        print(name,"answercount:",ancount, data[:16].hex())
        return data
    except Exception as e:
        print(name,"error",e)
for n in ["prices.internal","commons.local","prices","price.internal","prices.api"]:
    dns_query(n)
EOF"}

